#include "../Drivers/mcu/rcc/rcc.h"
#include "../Drivers/mcu/gpio/gpio.h"
#include "../Drivers/mcu/timer/timer.h"
#include "../Drivers/mcu/usart/usart.h"

int main (void)
{
	uint32_t data_rx = 0;

	rcc_init();

	gpio_init();
	/* Reset led */
	GPIOA->BSRR = (3UL << 9U);


	timer2_init();
	usart2_init();
	usart2_frame_config();

	while (1)
	{	
		data_rx = usart2_receive_rx();

		if (data_rx == 'S')
		{
			GPIOA->BRR = (3UL << 9U);
		}

		else if (data_rx == 'T')
		{
			GPIOA->BSRR = (3UL << 9U);
		}
		
	
	}
}
